// Lints only what the compiler cannot check (README, "Addresses").
import { defineConfig } from 'eslint/config'
import tseslint from 'typescript-eslint'

const ADDRESS_TYPES = ['EvmAddress', 'TronAddress', 'TonAddress', 'BtcAddress', 'SolanaAddress', 'TokenAddress']
const addressType = `TSTypeReference[typeName.name=/^(${ADDRESS_TYPES.join('|')})$/]`

export default defineConfig(
    // Generated by typechain.
    { ignores: ['scripts/config-cache/contracts/**'] },
    {
        files: ['src/**/*.ts', 'scripts/**/*.ts'],
        languageOptions: { parser: tseslint.parser },
        // Registered so that the code's eslint-disable comments name known rules; none of them is turned on.
        plugins: { '@typescript-eslint': tseslint.plugin },
        linterOptions: { reportUnusedDisableDirectives: 'off' },
        rules: {
            'no-restricted-syntax': [
                'error',
                {
                    selector: `TSAsExpression > ${addressType}, TSTypeAssertion > ${addressType}`,
                    message: 'Parse the address instead of casting to an address type (README, "Addresses").',
                },
            ],
        },
    },
    // The parsers are the only place that makes an address type.
    { files: ['src/addresses.ts'], rules: { 'no-restricted-syntax': 'off' } }
)
